#include <iostream>
#include <vector>
#include <string>
#include <queue>
using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.size();
    queue<int> qr, qd;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'R') qr.push(i);
        else qd.push(i);
    }
    while (!qr.empty() && !qd.empty()) {
        int r = qr.front(), d = qd.front();
        qr.pop();
        qd.pop();
        if (r < d) qr.push(r + n);
        else qd.push(d + n);
    }
    cout << (!qr.empty() ? "Radiant" : "Dire") << "\n";

    return 0;
}

